INCIDENTS = [
    {"id": "inc-001", "date": "2026-08-04", "text": "Incident on payments-api: 504 gateway timeouts. Root cause: Postgres connection pool exhausted, all 20 connections in use. Fix: raised max_connections from 20 to 50. Resolved in 18 minutes."},
    {"id": "inc-002", "date": "2026-08-06", "text": "Incident on auth-service: users could not log in after a deploy, 401 errors. Root cause: expired JWT signing key in the config secret. Fix: rotated the key and restarted the pods. Resolved in 25 minutes."},
    {"id": "inc-003", "date": "2026-08-09", "text": "Incident on search-api: latency spiked to 8 seconds, pods showed OOMKilled. Root cause: Elasticsearch node ran out of heap memory. Fix: increased heap to 8GB and reindexed. Resolved in 40 minutes."},
    {"id": "inc-004", "date": "2026-08-11", "text": "Incident on checkout: 502 errors on the payment page. Root cause: Redis cache cluster failover left stale connection strings. Fix: restarted the checkout pods to refresh connections. Resolved in 12 minutes. The restart worked."},
    {"id": "inc-005", "date": "2026-08-13", "text": "Incident on notification-service: emails stopped sending. Root cause: SMTP provider rate limit hit during a bulk campaign. Fix: throttled campaign sends and requested a limit increase. Resolved in 55 minutes."},
    {"id": "inc-006", "date": "2026-08-16", "text": "Incident on inventory-service: stock counts stale, Kafka consumer lag above 50,000 messages. Root cause: rebalance storm after a pod crash loop. Fix: fixed the crashing pod and reset the consumer group offsets. Resolved in 35 minutes."},
    {"id": "inc-007", "date": "2026-08-18", "text": "Incident on order-service: 500 errors on order creation, 'No space left on device' in logs. Root cause: log volume was full. Fix: rotated and compressed logs, added a log retention policy. Resolved in 20 minutes."},
    {"id": "inc-008", "date": "2026-08-20", "text": "Incident on payments-api: timeouts again with a different cause. Root cause: slow query with a missing index on the transactions table. Fix: added index on transactions(user_id, created_at). Resolved in 30 minutes. Restarting the service did NOT help."},
    {"id": "inc-009", "date": "2026-08-23", "text": "Incident on api-gateway: all HTTPS traffic failed with certificate errors. Root cause: TLS certificate expired, auto-renewal job had silently failed. Fix: renewed the certificate manually and fixed the renewal cron job. Resolved in 22 minutes."},
    {"id": "inc-010", "date": "2026-08-25", "text": "Incident on user-service: memory climbed steadily and pods restarted every hour after release v2.14. Root cause: memory leak in the profile image cache. Fix: rolled back to v2.13, then patched the cache with a size limit. Resolved in 45 minutes. Rollback worked immediately."},
    {"id": "inc-011", "date": "2026-08-27", "text": "Incident on auth-service: users randomly logged out. Root cause: Redis session store hit maxmemory and evicted sessions under the allkeys-lru policy. Fix: increased Redis maxmemory and set session TTLs. Resolved in 38 minutes."},
    {"id": "inc-012", "date": "2026-08-30", "text": "Incident on checkout: customers saw old prices after a promotion ended. Root cause: CDN cached the pricing response for too long. Fix: purged the CDN cache and lowered the pricing endpoint TTL. Resolved in 15 minutes."},
    {"id": "inc-013", "date": "2026-09-01", "text": "Incident on payments-api: 504 timeouts during a flash sale. Root cause: connection pool exhausted again, plus a connection leak in the refund handler that never released connections. Fix: raised max_connections from 50 to 80 and patched the refund handler to release connections. Resolved in 50 minutes. Restarting only bought a few minutes."},
    {"id": "inc-014", "date": "2026-09-03", "text": "Incident on search-api: queries slow after an index mapping change. Root cause: new mapping disabled doc_values on a sorted field. Fix: reverted the mapping and reindexed. Resolved in 60 minutes."},
    {"id": "inc-015", "date": "2026-09-05", "text": "Incident on notification-service: message queue backlog grew and workers kept crashing. Root cause: malformed email template caused a parser exception. Fix: corrected the template and drained the backlog. Resolved in 40 minutes."},
    {"id": "inc-016", "date": "2026-09-08", "text": "Incident on order-service: pods in CrashLoopBackOff after deploy. Root cause: ConfigMap was missing the DB_HOST environment variable. Fix: updated the ConfigMap and did a rollout restart. Resolved in 14 minutes."},
    {"id": "inc-017", "date": "2026-09-10", "text": "Incident across services: intermittent 'temporary failure in name resolution' errors. Root cause: CoreDNS pods were OOMKilled under load. Fix: raised CoreDNS memory limits and restarted CoreDNS. Resolved in 28 minutes. Restarting the affected application pods did NOT help."},
    {"id": "inc-018", "date": "2026-09-12", "text": "Incident on data-pipeline: nightly job overran and caused database lock contention in the morning. Root cause: two runs of the job overlapped. Fix: set the cron concurrency policy to Forbid and added a run lock. Resolved in 32 minutes."},
    {"id": "inc-019", "date": "2026-09-14", "text": "Incident on api-gateway: spike of 429 Too Many Requests for normal users. Root cause: rate limit misconfigured to 100 requests per hour instead of per minute after a deploy. Fix: corrected the limit and redeployed the gateway config. Resolved in 17 minutes."},
    {"id": "inc-020", "date": "2026-09-16", "text": "Incident on order-service: 5xx errors after a database failover. Root cause: pods still connected to the old primary. Fix: restarted the order-service pods to reconnect to the new primary. Resolved in 10 minutes. The restart worked."},
    {"id": "inc-021", "date": "2026-09-18", "text": "Incident on inventory-service: Kafka consumer lag grew again. Root cause: slow downstream call to the warehouse API. Fix: added a timeout and retry with backoff to the warehouse call. Resolved in 48 minutes. Adding more consumers alone did NOT help."},
    {"id": "inc-022", "date": "2026-09-21", "text": "Incident on payments-api: 502 errors right after a deploy. Root cause: readiness probe timeout was too aggressive, so pods were marked unready during startup. Fix: rolled back, then increased the probe initial delay and timeout. Resolved in 26 minutes."},
    {"id": "inc-023", "date": "2026-09-23", "text": "Incident on user-service: login latency spikes to 6 seconds. Root cause: database deadlocks from two concurrent profile update queries. Fix: changed the update order to be consistent and added a retry on deadlock. Resolved in 55 minutes."},
    {"id": "inc-024", "date": "2026-09-24", "text": "Incident on checkout: 502 errors on the payment page after a Redis failover. Root cause: same stale Redis connection strings as before. Fix: restarted the checkout pods. Resolved in 9 minutes. The restart worked, same as the earlier checkout incident."},
]